public class Main {
    public static void main(String[] args) throws Exception {
        FastReader r = new FastReader();
        int n = r.nextInt(), k = r.nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = r.nextLong();
        Arrays.sort(a);
        if (k > n || n > 2L * k) {
            System.out.println(-1);
            return;
        }
        int pairs = n - k;
        long answer = a[n - 1];
        // pair the smallest 2*pairs games from both ends; the rest stay alone
        for (int i = 0; i < pairs; i++) answer = Math.max(answer, a[i] + a[2 * pairs - 1 - i]);
        System.out.println(answer);
    }
}


final class FastReader {
    private final java.io.InputStream in = System.in;
    private final byte[] buf = new byte[1 << 16];
    private int len = 0, ptr = 0;

    private int read() throws java.io.IOException {
        if (ptr == len) {
            len = in.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) { len = 0; return -1; }
        }
        return buf[ptr++];
    }

    String next() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = read(); }
        return sb.toString();
    }

    long nextLong() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = read(); }
        return neg ? -r : r;
    }

    int nextInt() throws java.io.IOException { return (int) nextLong(); }
}

